using System.Data;
using Microsoft.EntityFrameworkCore;
namespace Produktionsplanung.App.Data;
public static class DatabaseSchemaUpdater{
 public static void Apply(AppDbContext db){
  BatchSchemaUpdater.BackupBeforeUpgrade(db);
  Sql(db,"CREATE TABLE IF NOT EXISTS ArticleMasters (Id INTEGER NOT NULL CONSTRAINT PK_ArticleMasters PRIMARY KEY AUTOINCREMENT,ArticleNumber TEXT NOT NULL,Name TEXT NOT NULL,Unit TEXT NOT NULL,DefaultIdealRatePerHour REAL NOT NULL DEFAULT 1,IsActive INTEGER NOT NULL DEFAULT 1,Notes TEXT NULL,CreatedAtUtc TEXT NOT NULL,UpdatedAtUtc TEXT NOT NULL);");Sql(db,"CREATE UNIQUE INDEX IF NOT EXISTS IX_ArticleMasters_ArticleNumber ON ArticleMasters (ArticleNumber);");Sql(db,"CREATE INDEX IF NOT EXISTS IX_ArticleMasters_Name ON ArticleMasters (Name);");
  EnsureColumn(db,"ProductionOrders","ArticleNumber","TEXT NOT NULL DEFAULT ''");EnsureColumn(db,"ProductionOrders","BatchNumber","TEXT NOT NULL DEFAULT ''");
  EnsureColumn(db,"ProductionActuals","ArticleNumberSnapshot","TEXT NULL");EnsureColumn(db,"ProductionActuals","BatchNumber","TEXT NULL");
  EnsureColumn(db,"Workstations","RequiredQualificationId","INTEGER NULL");EnsureColumn(db,"Workstations","RequiredQualificationLevel","INTEGER NOT NULL DEFAULT 0");db.Database.ExecuteSqlRaw("CREATE INDEX IF NOT EXISTS IX_Workstations_RequiredQualificationId ON Workstations (RequiredQualificationId);");
  var rulesExisted=TableExists(db,"WorkstationShiftRules");Sql(db,"CREATE TABLE IF NOT EXISTS WorkstationShiftRules (Id INTEGER NOT NULL CONSTRAINT PK_WorkstationShiftRules PRIMARY KEY AUTOINCREMENT,WorkstationId INTEGER NOT NULL,ShiftId INTEGER NOT NULL,Monday INTEGER NOT NULL,Tuesday INTEGER NOT NULL,Wednesday INTEGER NOT NULL,Thursday INTEGER NOT NULL,Friday INTEGER NOT NULL,Saturday INTEGER NOT NULL,Sunday INTEGER NOT NULL,FOREIGN KEY (WorkstationId) REFERENCES Workstations (Id) ON DELETE CASCADE,FOREIGN KEY (ShiftId) REFERENCES Shifts (Id) ON DELETE RESTRICT);");Sql(db,"CREATE UNIQUE INDEX IF NOT EXISTS IX_WorkstationShiftRules_WorkstationId_ShiftId ON WorkstationShiftRules (WorkstationId,ShiftId);");if(!rulesExisted)Sql(db,"INSERT INTO WorkstationShiftRules (WorkstationId,ShiftId,Monday,Tuesday,Wednesday,Thursday,Friday,Saturday,Sunday) SELECT w.Id,s.Id,1,1,1,1,1,1,1 FROM Workstations w CROSS JOIN Shifts s;");
  Sql(db,"CREATE TABLE IF NOT EXISTS OperatingCalendarDays (Id INTEGER NOT NULL CONSTRAINT PK_OperatingCalendarDays PRIMARY KEY AUTOINCREMENT,Date TEXT NOT NULL,Name TEXT NOT NULL,IsWorkingDay INTEGER NOT NULL,TargetHoursFactor REAL NOT NULL,Comment TEXT NULL);");Sql(db,"CREATE UNIQUE INDEX IF NOT EXISTS IX_OperatingCalendarDays_Date ON OperatingCalendarDays (Date);");Sql(db,"CREATE TABLE IF NOT EXISTS WorkTimeEntries (Id INTEGER NOT NULL CONSTRAINT PK_WorkTimeEntries PRIMARY KEY AUTOINCREMENT,EmployeeId INTEGER NOT NULL,Date TEXT NOT NULL,StartTime TEXT NOT NULL,EndTime TEXT NOT NULL,BreakMinutes INTEGER NOT NULL,Comment TEXT NULL,FOREIGN KEY (EmployeeId) REFERENCES Employees (Id) ON DELETE RESTRICT);");Sql(db,"CREATE INDEX IF NOT EXISTS IX_WorkTimeEntries_EmployeeId_Date ON WorkTimeEntries (EmployeeId,Date);");
  Sql(db,"CREATE TABLE IF NOT EXISTS ProductionOrders (Id INTEGER NOT NULL CONSTRAINT PK_ProductionOrders PRIMARY KEY AUTOINCREMENT,OrderNumber TEXT NOT NULL,Product TEXT NOT NULL,Description TEXT NULL,Quantity REAL NOT NULL,Unit TEXT NOT NULL,Priority TEXT NOT NULL,PlannedDate TEXT NOT NULL,PlannedStart TEXT NULL,PlannedEnd TEXT NULL,WorkstationId INTEGER NOT NULL,ShiftId INTEGER NULL,PlannedShiftCount INTEGER NOT NULL DEFAULT 1,RequiredStaff INTEGER NOT NULL,Status TEXT NOT NULL,Comment TEXT NULL,FOREIGN KEY (WorkstationId) REFERENCES Workstations (Id) ON DELETE RESTRICT,FOREIGN KEY (ShiftId) REFERENCES Shifts (Id) ON DELETE SET NULL);");EnsureColumn(db,"ProductionOrders","PlannedShiftCount","INTEGER NOT NULL DEFAULT 1");Sql(db,"CREATE UNIQUE INDEX IF NOT EXISTS IX_ProductionOrders_OrderNumber ON ProductionOrders (OrderNumber);");Sql(db,"CREATE INDEX IF NOT EXISTS IX_ProductionOrders_PlannedDate_WorkstationId_ShiftId ON ProductionOrders (PlannedDate,WorkstationId,ShiftId);");
  Sql(db,"CREATE TABLE IF NOT EXISTS ProductionRunSlots (Id INTEGER NOT NULL CONSTRAINT PK_ProductionRunSlots PRIMARY KEY AUTOINCREMENT,ProductionOrderId INTEGER NOT NULL,SequenceNumber INTEGER NOT NULL,Date TEXT NOT NULL,ShiftId INTEGER NOT NULL,FOREIGN KEY (ProductionOrderId) REFERENCES ProductionOrders (Id) ON DELETE CASCADE,FOREIGN KEY (ShiftId) REFERENCES Shifts (Id) ON DELETE RESTRICT);");Sql(db,"CREATE UNIQUE INDEX IF NOT EXISTS IX_ProductionRunSlots_ProductionOrderId_SequenceNumber ON ProductionRunSlots (ProductionOrderId,SequenceNumber);");Sql(db,"CREATE INDEX IF NOT EXISTS IX_ProductionRunSlots_Date_ShiftId ON ProductionRunSlots (Date,ShiftId);");
  Sql(db,"CREATE TABLE IF NOT EXISTS ProductionActuals (Id INTEGER NOT NULL CONSTRAINT PK_ProductionActuals PRIMARY KEY AUTOINCREMENT,ProductionOrderId INTEGER NOT NULL,ProductionRunSlotId INTEGER NULL,Date TEXT NOT NULL,TotalQuantity REAL NOT NULL,GoodQuantity REAL NOT NULL,ScrapQuantity REAL NOT NULL,PlannedProductionMinutes REAL NOT NULL,RunMinutes REAL NOT NULL,IdealRatePerHour REAL NOT NULL,ProductSnapshot TEXT NULL,UnitSnapshot TEXT NULL,WorkstationIdSnapshot INTEGER NULL,WorkstationNameSnapshot TEXT NULL,ShiftNameSnapshot TEXT NULL,Comment TEXT NULL,FOREIGN KEY (ProductionOrderId) REFERENCES ProductionOrders (Id) ON DELETE CASCADE,FOREIGN KEY (ProductionRunSlotId) REFERENCES ProductionRunSlots (Id) ON DELETE RESTRICT);");EnsureColumn(db,"ProductionActuals","ProductionRunSlotId","INTEGER NULL");EnsureColumn(db,"ProductionActuals","ProductSnapshot","TEXT NULL");EnsureColumn(db,"ProductionActuals","UnitSnapshot","TEXT NULL");EnsureColumn(db,"ProductionActuals","WorkstationIdSnapshot","INTEGER NULL");EnsureColumn(db,"ProductionActuals","WorkstationNameSnapshot","TEXT NULL");EnsureColumn(db,"ProductionActuals","ShiftNameSnapshot","TEXT NULL");Sql(db,"CREATE INDEX IF NOT EXISTS IX_ProductionActuals_ProductionOrderId_Date ON ProductionActuals (ProductionOrderId,Date);");Sql(db,"CREATE INDEX IF NOT EXISTS IX_ProductionActuals_ProductionRunSlotId ON ProductionActuals (ProductionRunSlotId);");
  Sql(db,"UPDATE ProductionActuals SET ProductionRunSlotId=(SELECT s.Id FROM ProductionRunSlots s WHERE s.ProductionOrderId=ProductionActuals.ProductionOrderId AND date(s.Date)=date(ProductionActuals.Date) LIMIT 1) WHERE ProductionRunSlotId IS NULL AND (SELECT COUNT(*) FROM ProductionRunSlots s WHERE s.ProductionOrderId=ProductionActuals.ProductionOrderId AND date(s.Date)=date(ProductionActuals.Date))=1;");
  // Capture current legacy labels once. A shift is historical only when a concrete run slot identifies it unambiguously.
  Sql(db,"UPDATE ProductionActuals SET ProductSnapshot=COALESCE(ProductSnapshot,(SELECT p.Product FROM ProductionOrders p WHERE p.Id=ProductionOrderId)),UnitSnapshot=COALESCE(UnitSnapshot,(SELECT p.Unit FROM ProductionOrders p WHERE p.Id=ProductionOrderId)),WorkstationIdSnapshot=COALESCE(WorkstationIdSnapshot,(SELECT p.WorkstationId FROM ProductionOrders p WHERE p.Id=ProductionOrderId)),WorkstationNameSnapshot=COALESCE(WorkstationNameSnapshot,(SELECT w.Name FROM ProductionOrders p JOIN Workstations w ON w.Id=p.WorkstationId WHERE p.Id=ProductionOrderId)),ShiftNameSnapshot=COALESCE(ShiftNameSnapshot,(SELECT s.Name FROM ProductionRunSlots r JOIN Shifts s ON s.Id=r.ShiftId WHERE r.Id=ProductionRunSlotId),'Legacy / nicht eindeutig') WHERE ProductSnapshot IS NULL OR UnitSnapshot IS NULL OR WorkstationNameSnapshot IS NULL OR ShiftNameSnapshot IS NULL;");
  Sql(db,"CREATE TABLE IF NOT EXISTS DowntimeEntries (Id INTEGER NOT NULL CONSTRAINT PK_DowntimeEntries PRIMARY KEY AUTOINCREMENT,ProductionActualId INTEGER NOT NULL,Reason TEXT NOT NULL,Minutes REAL NOT NULL,Comment TEXT NULL,FOREIGN KEY (ProductionActualId) REFERENCES ProductionActuals (Id) ON DELETE CASCADE);");Sql(db,"CREATE INDEX IF NOT EXISTS IX_DowntimeEntries_ProductionActualId ON DowntimeEntries (ProductionActualId);");Sql(db,"CREATE TRIGGER IF NOT EXISTS PreventOrderHistoryDeletion BEFORE DELETE ON ProductionOrders WHEN EXISTS (SELECT 1 FROM ProductionActuals WHERE ProductionOrderId=OLD.Id) BEGIN SELECT RAISE(ABORT,'Auftrag mit Ist-Produktion darf nicht gelöscht werden.'); END;");
  Sql(db,"CREATE TABLE IF NOT EXISTS OperationDefinitions (Id INTEGER NOT NULL CONSTRAINT PK_OperationDefinitions PRIMARY KEY AUTOINCREMENT,Code TEXT NOT NULL,Name TEXT NOT NULL,Description TEXT NULL,DefaultWorkstationId INTEGER NULL,DefaultMinutes REAL NOT NULL,RequiredStaff INTEGER NOT NULL,RequiredQualificationId INTEGER NULL,RequiredQualificationLevel INTEGER NOT NULL,IsActive INTEGER NOT NULL,FOREIGN KEY (DefaultWorkstationId) REFERENCES Workstations (Id) ON DELETE SET NULL,FOREIGN KEY (RequiredQualificationId) REFERENCES Qualifications (Id) ON DELETE SET NULL);");Sql(db,"CREATE UNIQUE INDEX IF NOT EXISTS IX_OperationDefinitions_Code ON OperationDefinitions (Code);");
  Sql(db,"CREATE TABLE IF NOT EXISTS ManufacturingRoutings (Id INTEGER NOT NULL CONSTRAINT PK_ManufacturingRoutings PRIMARY KEY AUTOINCREMENT,Product TEXT NOT NULL,Name TEXT NOT NULL,IsActive INTEGER NOT NULL);");Sql(db,"CREATE INDEX IF NOT EXISTS IX_ManufacturingRoutings_Product ON ManufacturingRoutings (Product);");
  Sql(db,"CREATE TABLE IF NOT EXISTS RoutingSteps (Id INTEGER NOT NULL CONSTRAINT PK_RoutingSteps PRIMARY KEY AUTOINCREMENT,ManufacturingRoutingId INTEGER NOT NULL,OperationDefinitionId INTEGER NOT NULL,SequenceNumber INTEGER NOT NULL,WorkstationId INTEGER NOT NULL,PlannedMinutes REAL NOT NULL,RequiredStaff INTEGER NOT NULL,FOREIGN KEY (ManufacturingRoutingId) REFERENCES ManufacturingRoutings (Id) ON DELETE CASCADE,FOREIGN KEY (OperationDefinitionId) REFERENCES OperationDefinitions (Id) ON DELETE RESTRICT,FOREIGN KEY (WorkstationId) REFERENCES Workstations (Id) ON DELETE RESTRICT);");Sql(db,"CREATE UNIQUE INDEX IF NOT EXISTS IX_RoutingSteps_ManufacturingRoutingId_SequenceNumber ON RoutingSteps (ManufacturingRoutingId,SequenceNumber);");
  Sql(db,"CREATE TABLE IF NOT EXISTS JobCards (Id INTEGER NOT NULL CONSTRAINT PK_JobCards PRIMARY KEY AUTOINCREMENT,ProductionOrderId INTEGER NOT NULL,RoutingStepId INTEGER NULL,SequenceNumber INTEGER NOT NULL,OperationCode TEXT NOT NULL,OperationName TEXT NOT NULL,WorkstationId INTEGER NOT NULL,EmployeeId INTEGER NULL,RequiredQualificationId INTEGER NULL,RequiredQualificationNameSnapshot TEXT NULL,RequiredQualificationLevel INTEGER NOT NULL DEFAULT 0,PlannedMinutes REAL NOT NULL,RequiredStaff INTEGER NOT NULL,Status TEXT NOT NULL,StartedAtUtc TEXT NULL,PauseStartedAtUtc TEXT NULL,RunMinutes REAL NOT NULL,CompletedAtUtc TEXT NULL,GoodQuantity REAL NOT NULL,ScrapQuantity REAL NOT NULL,Comment TEXT NULL,FOREIGN KEY (ProductionOrderId) REFERENCES ProductionOrders (Id) ON DELETE CASCADE,FOREIGN KEY (RoutingStepId) REFERENCES RoutingSteps (Id) ON DELETE SET NULL,FOREIGN KEY (WorkstationId) REFERENCES Workstations (Id) ON DELETE RESTRICT,FOREIGN KEY (EmployeeId) REFERENCES Employees (Id) ON DELETE SET NULL,FOREIGN KEY (RequiredQualificationId) REFERENCES Qualifications (Id) ON DELETE SET NULL);");EnsureColumn(db,"JobCards","RequiredQualificationId","INTEGER NULL");EnsureColumn(db,"JobCards","RequiredQualificationNameSnapshot","TEXT NULL");EnsureColumn(db,"JobCards","RequiredQualificationLevel","INTEGER NOT NULL DEFAULT 0");Sql(db,"CREATE UNIQUE INDEX IF NOT EXISTS IX_JobCards_ProductionOrderId_SequenceNumber ON JobCards (ProductionOrderId,SequenceNumber);");Sql(db,"CREATE INDEX IF NOT EXISTS IX_JobCards_WorkstationId_Status ON JobCards (WorkstationId,Status);");Sql(db,"CREATE INDEX IF NOT EXISTS IX_JobCards_RequiredQualificationId ON JobCards (RequiredQualificationId);");Sql(db,"UPDATE JobCards SET RequiredQualificationId=COALESCE(RequiredQualificationId,(SELECT o.RequiredQualificationId FROM RoutingSteps r JOIN OperationDefinitions o ON o.Id=r.OperationDefinitionId WHERE r.Id=JobCards.RoutingStepId)),RequiredQualificationNameSnapshot=COALESCE(RequiredQualificationNameSnapshot,(SELECT q.Name FROM RoutingSteps r JOIN OperationDefinitions o ON o.Id=r.OperationDefinitionId LEFT JOIN Qualifications q ON q.Id=o.RequiredQualificationId WHERE r.Id=JobCards.RoutingStepId)),RequiredQualificationLevel=CASE WHEN RequiredQualificationLevel>0 THEN RequiredQualificationLevel ELSE COALESCE((SELECT o.RequiredQualificationLevel FROM RoutingSteps r JOIN OperationDefinitions o ON o.Id=r.OperationDefinitionId WHERE r.Id=JobCards.RoutingStepId),0) END WHERE RoutingStepId IS NOT NULL;");
  Sql(db,"CREATE TABLE IF NOT EXISTS UserAccounts (Id INTEGER NOT NULL CONSTRAINT PK_UserAccounts PRIMARY KEY AUTOINCREMENT,Username TEXT NOT NULL,DisplayName TEXT NOT NULL,PasswordHash TEXT NOT NULL,PasswordSalt TEXT NOT NULL,Role TEXT NOT NULL,IsActive INTEGER NOT NULL,CreatedAtUtc TEXT NOT NULL,LastLoginAtUtc TEXT NULL);");Sql(db,"CREATE UNIQUE INDEX IF NOT EXISTS IX_UserAccounts_Username ON UserAccounts (Username);");Sql(db,"CREATE TABLE IF NOT EXISTS AuditLogs (Id INTEGER NOT NULL CONSTRAINT PK_AuditLogs PRIMARY KEY AUTOINCREMENT,TimestampUtc TEXT NOT NULL,Username TEXT NOT NULL,Action TEXT NOT NULL,EntityType TEXT NOT NULL,EntityId TEXT NULL,Details TEXT NULL);");Sql(db,"CREATE INDEX IF NOT EXISTS IX_AuditLogs_TimestampUtc ON AuditLogs (TimestampUtc);");Sql(db,"CREATE INDEX IF NOT EXISTS IX_AuditLogs_Username ON AuditLogs (Username);");
  BatchSchemaUpdater.Apply(db);
 }
 private static void Sql(AppDbContext db,string sql)=>db.Database.ExecuteSqlRaw(sql);private static bool TableExists(AppDbContext db,string name){var c=db.Database.GetDbConnection();var close=c.State!=ConnectionState.Open;if(close)c.Open();try{using var cmd=c.CreateCommand();cmd.CommandText="SELECT COUNT(1) FROM sqlite_master WHERE type='table' AND name=$name;";var p=cmd.CreateParameter();p.ParameterName="$name";p.Value=name;cmd.Parameters.Add(p);return Convert.ToInt32(cmd.ExecuteScalar())>0;}finally{if(close)c.Close();}}private static void EnsureColumn(AppDbContext db,string table,string column,string definition){var c=db.Database.GetDbConnection();var close=c.State!=ConnectionState.Open;if(close)c.Open();try{using var check=c.CreateCommand();check.CommandText=$"PRAGMA table_info(\"{table}\");";using var r=check.ExecuteReader();var exists=false;while(r.Read())if(string.Equals(r.GetString(1),column,StringComparison.OrdinalIgnoreCase)){exists=true;break;}r.Close();if(exists)return;using var alter=c.CreateCommand();alter.CommandText=$"ALTER TABLE \"{table}\" ADD COLUMN \"{column}\" {definition};";alter.ExecuteNonQuery();}finally{if(close)c.Close();}}
}
